insert into public.courses values ('arithmetic','{"id":"arithmetic","title":"Everyday arithmetic","subject":"Arithmetic","grades":[0,1,2,3,4],"description":"Build confidence with numbers, one small discovery at a time.","units":[{"id":"addition","title":"Addition","x":80,"y":40,"requires":[],"lessons":[{"id":"addition","title":"Adding with confidence","explanation":"Addition combines quantities. You can split a number to make a friendly ten.","example":"8 + 5 = 8 + 2 + 3 = 13.","questions":[{"id":"a1","prompt":"What is 7 + 6?","answer":"13","hint":"Make ten: 7 + 3 + 3.","explanation":"7 + 3 = 10; 10 + 3 = 13.","kind":"numeric","difficulty":"easy"},{"id":"a2","prompt":"What is 28 + 15?","answer":"43","hint":"Add tens, then ones.","explanation":"28 + 10 = 38; 38 + 5 = 43.","kind":"numeric","difficulty":"easy"}]}]},{"id":"multiply","title":"Multiplication","x":350,"y":240,"requires":["addition"],"lessons":[{"id":"multiply","title":"Equal groups","explanation":"Multiplication counts equal groups.","example":"4 groups of 3 make 4 × 3 = 12.","questions":[{"id":"m1","prompt":"Five bags each have 4 apples. How many apples?","answer":"20","hint":"Add four five times.","explanation":"5 × 4 = 20 apples.","kind":"numeric","difficulty":"easy"},{"id":"m2","prompt":"What is 6 × 7?","answer":"42","hint":"Use 5 × 7 + 7.","explanation":"35 + 7 = 42.","kind":"numeric","difficulty":"easy"}]}]}]}') on conflict(id) do update set content=excluded.content;
