insert into public.courses values ('fractions','{"id":"fractions","title":"Making sense of fractions","subject":"Arithmetic","grades":[3,4,5,6],"description":"See the whole picture, and all the parts that make it.","units":[{"id":"parts","title":"Equal parts","x":100,"y":40,"requires":[],"lessons":[{"id":"fractions","title":"Equivalent fractions","explanation":"Multiplying numerator and denominator by the same nonzero number keeps a fraction equal.","example":"1/2 = 2/4 = 3/6.","questions":[{"id":"r1","prompt":"Write 1/2 as a decimal.","answer":"0.5","hint":"Divide 1 by 2.","explanation":"1 ÷ 2 = 0.5. A fraction such as 2/4 is also accepted.","kind":"numeric","difficulty":"easy"},{"id":"r2","prompt":"What is 1/4 + 2/4?","answer":"0.75","hint":"Add the numerators; keep the denominator.","explanation":"1/4 + 2/4 = 3/4 = 0.75.","kind":"numeric","difficulty":"easy"}]}]}]}') on conflict(id) do update set content=excluded.content;
