insert into public.courses values ('algebra','{"id":"algebra","title":"Algebra I","subject":"Algebra I","grades":[7,8,9,10],"description":"From your first variable to a world of possibilities.","units":[{"id":"foundations","title":"Foundations","x":260,"y":0,"requires":[],"lessons":[{"id":"order","title":"Order of operations","explanation":"Evaluate parentheses, then powers, then multiplication and division, then addition and subtraction.","example":"3 + 2 × 4 = 3 + 8 = 11.","questions":[{"id":"o1","prompt":"Evaluate 6 + 3 × 4.","answer":"18","hint":"Multiply first.","explanation":"3 × 4 = 12, then 6 + 12 = 18.","kind":"numeric","difficulty":"easy"},{"id":"o2","prompt":"Evaluate (6 + 3) × 4.","answer":"36","hint":"Start inside the parentheses.","explanation":"6 + 3 = 9, then 9 × 4 = 36.","kind":"numeric","difficulty":"easy"}]}]},{"id":"expressions","title":"Expressions","x":80,"y":170,"requires":["foundations"],"lessons":[{"id":"combine","title":"Combine like terms","explanation":"Terms with the same variable and exponent can be added by combining coefficients.","example":"3x + 2x = (3 + 2)x = 5x.","questions":[{"id":"e1","prompt":"Simplify 4x + 3x.","answer":"7x","hint":"Add the coefficients.","explanation":"(4 + 3)x = 7x.","kind":"expression","difficulty":"easy"},{"id":"e2","prompt":"Evaluate 2x + 5 when x = 3.","answer":"11","hint":"Replace x with 3.","explanation":"2 × 3 + 5 = 6 + 5 = 11.","kind":"numeric","difficulty":"easy"}]}]},{"id":"equations","title":"Linear equations","x":440,"y":170,"requires":["foundations"],"lessons":[{"id":"solve","title":"Solve linear equations","explanation":"Keep an equation balanced by doing the same operation on both sides.","example":"2x + 4 = 12 → 2x = 8 → x = 4.","questions":[{"id":"l1","prompt":"Solve 3x + 5 = 20. Enter x.","answer":"5","hint":"Subtract 5, then divide by 3.","explanation":"3x = 15, so x = 5.","kind":"numeric","difficulty":"easy"},{"id":"l2","prompt":"Solve 4x − 8 = 16. Enter x.","answer":"6","hint":"Add 8 to both sides.","explanation":"4x = 24, so x = 6.","kind":"numeric","difficulty":"easy"}]}]},{"id":"inequalities","title":"Inequalities","x":0,"y":350,"requires":["expressions","equations"],"lessons":[{"id":"inequality","title":"Compare solutions","explanation":"An inequality describes a range. Reverse the inequality when multiplying or dividing by a negative number.","example":"−2x < 6 → x > −3.","questions":[{"id":"i1","prompt":"Solve 2x + 1 < 9.","answer":"x < 4","hint":"Subtract 1 and divide by 2.","explanation":"2x < 8 gives x < 4.","kind":"choice","choices":["x < 4","x > 4","x < 5"],"difficulty":"easy"},{"id":"i2","prompt":"Solve −3x > 12.","answer":"x < -4","hint":"Division by a negative reverses the sign.","explanation":"Divide both sides by −3 to get x < −4.","kind":"choice","choices":["x > -4","x < -4","x < 4"],"difficulty":"easy"}]}]},{"id":"functions","title":"Functions","x":260,"y":350,"requires":["expressions","equations"],"lessons":[{"id":"function","title":"Inputs and outputs","explanation":"A function assigns exactly one output to each input. Substitute the input for x.","example":"For f(x) = 2x + 1, f(3) = 7.","questions":[{"id":"f1","prompt":"If f(x) = 3x − 2, find f(4).","answer":"10","hint":"Substitute 4 for x.","explanation":"3 × 4 − 2 = 10.","kind":"numeric","difficulty":"easy"},{"id":"f2","prompt":"If g(x) = x² + 1, find g(−3).","answer":"10","hint":"Square −3 before adding 1.","explanation":"(−3)² + 1 = 9 + 1 = 10.","kind":"numeric","difficulty":"easy"}]}]},{"id":"systems","title":"Systems","x":520,"y":350,"requires":["equations"],"lessons":[{"id":"system","title":"Solve a system","explanation":"A solution satisfies both equations. Substitution replaces a variable with an equal expression.","example":"y = x + 1 and x + y = 5 → 2x + 1 = 5 → x = 2, y = 3.","questions":[{"id":"s1","prompt":"If y = x + 2 and x + y = 10, find x.","answer":"4","hint":"Replace y with x + 2.","explanation":"x + x + 2 = 10 → 2x = 8 → x = 4.","kind":"numeric","difficulty":"easy"},{"id":"s2","prompt":"For that same system, find y.","answer":"6","hint":"Use x = 4 in y = x + 2.","explanation":"y = 4 + 2 = 6.","kind":"numeric","difficulty":"easy"}]}]},{"id":"quadratics","title":"Quadratics","x":260,"y":530,"requires":["functions","systems"],"lessons":[{"id":"quadratic","title":"Quadratic roots","explanation":"A quadratic can have two real roots. If a product equals zero, at least one factor is zero.","example":"x² − 9 = (x − 3)(x + 3), so x = 3 or x = −3.","questions":[{"id":"q1","prompt":"What are the roots of x² − 16 = 0?","answer":"-4 and 4","hint":"Which two numbers square to 16?","explanation":"x² = 16 gives x = −4 or x = 4.","kind":"choice","choices":["-4 and 4","4 only","-8 and 8"],"difficulty":"medium"},{"id":"q2","prompt":"What is the positive root of x² − 25 = 0?","answer":"5","hint":"Take the positive square root of 25.","explanation":"x² = 25, so the positive root is 5.","kind":"numeric","difficulty":"easy"}]}]}]}') on conflict(id) do update set content=excluded.content;
