insert into public.units values ('quadratics','algebra','{"id":"quadratics","title":"Quadratics","x":260,"y":530,"requires":["functions","systems"],"lessons":[{"id":"quadratic","title":"Quadratic roots","explanation":"A quadratic can have two real roots. If a product equals zero, at least one factor is zero.","example":"x² − 9 = (x − 3)(x + 3), so x = 3 or x = −3.","questions":[{"id":"q1","prompt":"What are the roots of x² − 16 = 0?","answer":"-4 and 4","hint":"Which two numbers square to 16?","explanation":"x² = 16 gives x = −4 or x = 4.","kind":"choice","choices":["-4 and 4","4 only","-8 and 8"],"difficulty":"medium"},{"id":"q2","prompt":"What is the positive root of x² − 25 = 0?","answer":"5","hint":"Take the positive square root of 25.","explanation":"x² = 25, so the positive root is 5.","kind":"numeric","difficulty":"easy"}]}]}') on conflict(id) do update set content=excluded.content;
